import { appendFile } from "node:fs/promises";

import { basic } from "../../../src/job-types/basic.mjs";
import { exitWorkerOnDrain } from "../../support/exit-worker-on-drain.mjs";

let alreadyBuilt = false;

basic(async function ({
  autogeneratedComment,
  printSubtreeList,
  resetConsole,
  sleep,
}) {
  if (alreadyBuilt) {
    return;
  }

  alreadyBuilt = true;

  resetConsole();
  printSubtreeList({ title: "items", items: ["b", "a"] });
  await sleep({ delay: 0 });
  await appendFile(process.env.JARMUZ_RESULT_FILE, autogeneratedComment);
});

exitWorkerOnDrain();
